verifier.cmd:
node --test test/style.test.mjs >/dev/null 2>&1 || { echo 'style test fails on the clean tree'; exit 1; }; for v in long:src/engine/importers/project.mjs imp:src/server/oauth.mjs cst:bin/memev.mjs dup:src/engine/util.mjs; do k=${v%%:*}; f=${v#*:}; d=$(mktemp -d); cp -R src bin scripts test vendor templates package.json "$d"/; case $k in long) printf '
// %0158d
' 0 >> "$d/$f";; imp) printf "
import { sep as srUnusedImport } from 'node:path';
" >> "$d/$f";; cst) printf '
const srUnusedConst = 1;
' >> "$d/$f";; dup) printf '
export const srDupKey = { a: 1, a: 2 };
' >> "$d/$f";; esac; if (cd "$d" && node --test test/style.test.mjs >/dev/null 2>&1); then echo "style test still passes with $k added to $f"; rm -rf "$d"; exit 1; fi; rm -rf "$d"; done; exit 0
